#ifndef FCAROUGE_SPARSE_LINEAR_ALGEBRA_SPARSE_LINEAR_ALGEBRA_TPP
#define FCAROUGE_SPARSE_LINEAR_ALGEBRA_SPARSE_LINEAR_ALGEBRA_TPP

//! @file
//! @brief The member definitions of the compile-time sparsity pattern matrix.






#include <array>
#include <concepts>
#include <cstddef>
#include <type_traits>

namespace fcarouge {
template <typename Type, auto Pattern>
  requires sparsity_pattern<decltype(Pattern)>
template <std::same_as<Type>... Values>
  requires(sizeof...(Values) == Pattern.count and Pattern.count > 0)
constexpr sparse_matrix<Type, Pattern>::sparse_matrix(const Values &...stored) {
  values = std::array<Type, Pattern.count>{stored...};
}

template <typename Type, auto Pattern>
  requires sparsity_pattern<decltype(Pattern)>
template <auto Other>
  requires(sparsity_pattern<decltype(Other)> and
           sparse::is_subset_of<Other, Pattern>)
constexpr sparse_matrix<Type, Pattern>::sparse_matrix(
    const sparse_matrix<Type, Other> &other) {
  for (std::size_t i{0}; i < Pattern.count; ++i) {
    const std::size_t index{
        sparse_linear_algebra::internal::projection<Other, Pattern>[i]};

    if (index != sparse::absent) {
      values[i] = other.values[index];
    }
  }
}

template <typename Type, auto Pattern>
  requires sparsity_pattern<decltype(Pattern)>
constexpr auto
sparse_matrix<Type, Pattern>::operator[](std::size_t row,
                                         std::size_t column) const -> Type {
  if constexpr (sparse_linear_algebra::internal::is_dense<Pattern>) {
    return values[(row * Pattern.columns) + column];
  } else {
    const std::size_t index{Pattern.index_of(row, column)};

    return index == sparse::absent ? Type{} : values[index];
  }
}

template <typename Type, auto Pattern>
  requires sparsity_pattern<decltype(Pattern)>
constexpr auto sparse_matrix<Type, Pattern>::operator[](std::size_t row,
                                                        std::size_t column)
    -> Type &
  requires sparse_linear_algebra::internal::is_dense<Pattern>
{
  return values[(row * Pattern.columns) + column];
}

template <typename Type, auto Pattern>
  requires sparsity_pattern<decltype(Pattern)>
template <std::size_t Row, std::size_t Column>
  requires(Pattern.stores(Row, Column))
constexpr auto sparse_matrix<Type, Pattern>::operator[](
    std::integral_constant<std::size_t, Row> row,
    std::integral_constant<std::size_t, Column> column) -> Type & {
  static_cast<void>(row);
  static_cast<void>(column);

  return at<Row, Column>();
}

template <typename Type, auto Pattern>
  requires sparsity_pattern<decltype(Pattern)>
template <std::size_t Row, std::size_t Column>
  requires(Row < Pattern.rows and Column < Pattern.columns)
constexpr auto sparse_matrix<Type, Pattern>::operator[](
    std::integral_constant<std::size_t, Row> row,
    std::integral_constant<std::size_t, Column> column) const -> Type {
  static_cast<void>(row);
  static_cast<void>(column);

  return at<Row, Column>();
}

template <typename Type, auto Pattern>
  requires sparsity_pattern<decltype(Pattern)>
template <std::size_t Row, std::size_t Column>
  requires(Pattern.stores(Row, Column))
constexpr auto sparse_matrix<Type, Pattern>::at() -> Type & {
  static constexpr std::size_t index{Pattern.index_of(Row, Column)};

  return values[index];
}

template <typename Type, auto Pattern>
  requires sparsity_pattern<decltype(Pattern)>
template <std::size_t Row, std::size_t Column>
  requires(Row < Pattern.rows and Column < Pattern.columns)
constexpr auto sparse_matrix<Type, Pattern>::at() const -> Type {
  static constexpr std::size_t index{Pattern.index_of(Row, Column)};

  if constexpr (index == sparse::absent) {
    return Type{};
  } else {
    return values[index];
  }
}
} // namespace fcarouge

#endif // FCAROUGE_SPARSE_LINEAR_ALGEBRA_SPARSE_LINEAR_ALGEBRA_TPP


namespace fcarouge {
//! @name Algorithms
//! @{

template <typename Type, sparsity_pattern auto Lhs, sparsity_pattern auto Rhs>
  requires((Lhs.rows == 1 or Lhs.columns == 1) and
           (Rhs.rows == 1 or Rhs.columns == 1) and
           Lhs.rows * Lhs.columns == Rhs.rows * Rhs.columns)
[[nodiscard]] constexpr auto dot(const sparse_matrix<Type, Lhs> &lhs,
                                 const sparse_matrix<Type, Rhs> &rhs) -> Type;

template <std::floating_point Type, sparsity_pattern auto Pattern>
[[nodiscard]] constexpr auto
matrix_frob_norm(const sparse_matrix<Type, Pattern> &value) -> Type;

template <typename Type, sparsity_pattern auto Pattern>
[[nodiscard]] constexpr auto
matrix_inf_norm(const sparse_matrix<Type, Pattern> &value) -> Type;

template <typename Type, sparsity_pattern auto Pattern>
[[nodiscard]] constexpr auto
matrix_one_norm(const sparse_matrix<Type, Pattern> &value) -> Type;

template <typename Type, sparsity_pattern auto Lhs, sparsity_pattern auto Rhs>
  requires(Lhs.rows == Rhs.rows and Lhs.columns == Rhs.columns)
[[nodiscard]] constexpr auto operator==(const sparse_matrix<Type, Lhs> &lhs,
                                        const sparse_matrix<Type, Rhs> &rhs)
    -> bool;

template <typename Type, sparsity_pattern auto Lhs, sparsity_pattern auto Rhs>
  requires(Lhs.rows == Rhs.rows and Lhs.columns == Rhs.columns)
[[nodiscard]] constexpr auto operator+(const sparse_matrix<Type, Lhs> &lhs,
                                       const sparse_matrix<Type, Rhs> &rhs)
    -> sparse_matrix<Type, sparse::pattern_union<Lhs, Rhs>>;

template <typename Type, sparsity_pattern auto Lhs, sparsity_pattern auto Rhs>
  requires(Lhs.rows == Rhs.rows and Lhs.columns == Rhs.columns)
[[nodiscard]] constexpr auto operator-(const sparse_matrix<Type, Lhs> &lhs,
                                       const sparse_matrix<Type, Rhs> &rhs)
    -> sparse_matrix<Type, sparse::pattern_union<Lhs, Rhs>>;

template <typename Type, sparsity_pattern auto Pattern>
[[nodiscard]] constexpr auto
operator-(const sparse_matrix<Type, Pattern> &value)
    -> sparse_matrix<Type, Pattern>;

template <typename Type, sparsity_pattern auto Lhs, sparsity_pattern auto Rhs>
  requires(Lhs.columns == Rhs.rows)
[[nodiscard]] constexpr auto operator*(const sparse_matrix<Type, Lhs> &lhs,
                                       const sparse_matrix<Type, Rhs> &rhs)
    -> sparse_matrix<Type, sparse::pattern_product<Lhs, Rhs>>;

template <typename Type, sparsity_pattern auto Pattern>
[[nodiscard]] constexpr auto operator*(const sparse_matrix<Type, Pattern> &lhs,
                                       const std::type_identity_t<Type> &rhs)
    -> sparse_matrix<Type, Pattern>;

template <typename Type, sparsity_pattern auto Pattern>
[[nodiscard]] constexpr auto operator*(const std::type_identity_t<Type> &lhs,
                                       const sparse_matrix<Type, Pattern> &rhs)
    -> sparse_matrix<Type, Pattern>;

template <typename Type, sparsity_pattern auto Lhs, sparsity_pattern auto Rhs>
  requires(Rhs.rows == Rhs.columns and Lhs.columns == Rhs.rows and
           sparse::structural_rank<Rhs> == Rhs.rows)
[[nodiscard]] constexpr auto operator/(const sparse_matrix<Type, Lhs> &lhs,
                                       const sparse_matrix<Type, Rhs> &rhs)
    -> sparse_matrix<Type, sparse::pattern_quotient<Lhs, Rhs>>;

template <typename Type, sparsity_pattern auto Pattern>
[[nodiscard]] constexpr auto operator/(const sparse_matrix<Type, Pattern> &lhs,
                                       const std::type_identity_t<Type> &rhs)
    -> sparse_matrix<Type, Pattern>;

template <typename Type, sparsity_pattern auto Pattern>
[[nodiscard]] constexpr auto
transposed(const sparse_matrix<Type, Pattern> &value)
    -> sparse_matrix<Type, sparse::pattern_transpose<Pattern>>;

//! @}
} // namespace fcarouge

#endif // FCAROUGE_SPARSE_LINEAR_ALGEBRA_HPP
